import { useEffect, useState } from "react";
export default function Clock() {
  const [seconds, setSeconds] = useState(0);
  useEffect(() => {
    const timer = setInterval(() => setSeconds(n => n + 1), 1000);
    return () => clearInterval(timer);
  }, []);
  return <p>Seconds: {seconds}</p>;
}
